import {stages,pads} from './topic.js';
import {detailArt} from './primitives.js';
export class Inspector{
 constructor({clock,onSelect,onClose}){this.clock=clock;this.dialog=document.querySelector('#inspector');this.selected=null;this.select=document.querySelector('#station-select');this.select.innerHTML=stages.map((s,i)=>`<option value="${i}">0${i+1} · ${s.label}</option>`).join('');document.querySelector('#text-steps').innerHTML=stages.map(s=>`<li>${s.label}：${s.description}</li>`).join('');this.select.addEventListener('change',()=>onSelect(+this.select.value));document.querySelector('#close-panel').addEventListener('click',onClose);this.dialog.addEventListener('cancel',e=>{e.preventDefault();onClose();});document.querySelector('#seek-step').addEventListener('click',()=>{clock.seek(stages[this.selected].time);document.querySelector('#announcement').textContent=`已定位${stages[this.selected].label}完成狀態，動畫暫停。`;});}
 open(i,trigger){this.trigger=trigger||document.activeElement;this.clock.openPanel();this.update(i);if(!this.dialog.open)this.dialog.showModal();document.querySelector('#close-panel').focus();}
 update(i){this.selected=i;const s=stages[i];this.select.value=i;document.querySelector('#panel-title').textContent=s.label;document.querySelector('#in-out').textContent=s.io;document.querySelector('#detail-description').textContent=s.description;document.querySelector('#detail-points').innerHTML=s.points.map(p=>`<li>${p}</li>`).join('');document.querySelector('#detail-simplification').textContent=s.simplification;const art=document.querySelector('#detail-art');art.innerHTML=detailArt(i);art.querySelectorAll('[data-saw]').forEach(p=>p.setAttribute('stroke-dashoffset',0));const hole=art.querySelector('#detail-hole');if(hole)hole.setAttribute('visibility','hidden');art.querySelectorAll('[data-wire]').forEach(p=>p.setAttribute('stroke-dashoffset',i>=2?0:1));art.querySelectorAll('[data-bond],[data-end]').forEach(p=>p.setAttribute('visibility',i>=2?'visible':'hidden'));const body=art.querySelector('#detail-body');if(body)body.setAttribute('height',i>=3?76:0);const pin=art.querySelector('#detail-pin-one');if(pin)pin.setAttribute('visibility',i>=3?'visible':'hidden');const metal=art.querySelector('#detail-temporary');if(metal&&i>=4)metal.setAttribute('visibility','hidden');if(i>=4)art.querySelectorAll('.finger').forEach((p,n)=>{const s=pads[n].side,y=pads[n].finger[1];p.setAttribute('d',`M${s*24} ${y-4}H${s*48}V${y+4}H${s*24}Z`);});}
 close(){this.dialog.close();this.clock.closePanel();this.trigger?.focus();}
}
